/* Speculative Score-Draft Starter for Tone.js */
// Set global tempo and swing
Tone.Transport.bpm.value = 120;

// Add master channel effects for punch and grit
const masterComp = new Tone.Compressor(-12, 4).toDestination();
const masterDist = new Tone.Distortion(0.1).connect(masterComp);

// Kick: MembraneSynth with drive
const kick = new Tone.MembraneSynth({
  pitchDecay: 0.04,
  octaves: 6,
  oscillator: { type: 'sine' },
  envelope: { attack: 0.001, decay: 0.2, sustain: 0, release: 0.1 },
  volume: -2,
}).connect(masterDist);
const kickPattern = new Tone.Sequence((time, note) => {
  kick.triggerAttack(note, time);
}, ['C1', 'C1', 'C1', 'C1'], '4n').start(0);

// Snare: NoiseSynth with a tight envelope and filter
const snare = new Tone.NoiseSynth({
  noise: { type: 'white' },
  envelope: { attack: 0.001, decay: 0.12, sustain: 0 },
  volume: -5,
}).connect(masterDist);
const snareEnv = new Tone.AmplitudeEnvelope({ attack: 0.001, decay: 0.12, sustain: 0, release: 0.05 }).connect(masterDist);
const snareFilter = new Tone.Filter(2000, 'highpass').connect(snareEnv);
snare.connect(snareFilter);
const snarePattern = new Tone.Sequence((time) => {
  snareEnv.triggerAttack(time);
}, [null, 'x', null, 'x'], '4n').start(0);

// Hats: MetalSynth, one for closed, one for open
const hats = new Tone.MetalSynth({
  frequency: 200,
  harmonicity: 5.1,
  modulationIndex: 32,
  envelope: { attack: 0.001, decay: 0.08, release: 0.05 },
  volume: -15
}).connect(masterDist);
const hatPattern = new Tone.Sequence((time) => {
  hats.triggerAttack(time);
}, ['x', 'x', 'x', 'x', 'x', 'x', 'x', 'x'], '8n').start(0);
